// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A buffered flush whose preflight projects map growth must grow the maps before its first native write instead of
 * filling the map, aborting the native transaction and replaying every statement.
 */
class LmdbPreflightGrowthTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void bulkFlushGrowsMapsBeforeWritingInsteadOfReplaying(@TempDir File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setTripleDBSize(1024L * 1024L);
		config.setValueDBSize(1024L * 1024L);
		config.setAutoGrow(true);
		config.setForceSync(false);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI predicate = VF.createIRI("urn:test:p");
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				for (int i = 0; i < 20_000; i++) {
					connection.add(VF.createIRI("urn:test:s" + i), predicate,
							VF.createLiteral("value-" + i + "-" + "x".repeat(40)));
				}
				connection.commit();
				assertEquals(20_000, connection.size());
			}
			MapGrowthMetrics.Snapshot growth = store.getBackingStore().growthMetricsSnapshot();
			assertTrue(growth.tripleStoreResizes() + growth.valueStoreResizes() > 0,
					"the one-megabyte maps must have grown during the load");
			assertEquals(0, growth.statementReplays(),
					"projected growth must be applied before the first native write, not by replaying the flush");
		} finally {
			repository.shutDown();
		}
	}
}
